'use strict';
/**
 * scripts/build-interpreter-bundle.js — Gộp toàn bộ module CommonJS
 * (knowledge/*.js, lib/*.js, index.js) thành 1 file browser bundle
 * (qimen-interpreter.bundle.js) với mini module registry.
 *
 * Chạy: node scripts/build-interpreter-bundle.js
 * Bundle: global.KYMON_IQ = public API (window trong browser).
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const FILES = [
    'knowledge/five-elements.js',
    'knowledge/palaces.js',
    'knowledge/doors.js',
    'knowledge/stars.js',
    'knowledge/deities.js',
    'knowledge/stems.js',
    'knowledge/question-types.js',
    'knowledge/yongshen.js',
    'knowledge/patterns.js',
    'knowledge/rules.js',
    'lib/chartNormalizer.js',
    'lib/qimenRelations.js',
    'lib/yongShenResolver.js',
    'lib/ruleEngine.js',
    'lib/interpretationSynthesizer.js',
    'lib/adviceEngine.js',
    'lib/explain.js',
    'lib/interpret.js',
    'lib/score.js',
    'index.js'
];

const L = [];
L.push('/* Qimen Interpretation Engine — browser bundle (generated by scripts/build-interpreter-bundle.js). DO NOT EDIT. */');
L.push('(function (global) {');
L.push('  "use strict";');
L.push('  var modules = {};');
L.push('  var cache = {};');

for (const f of FILES) {
    const src = fs.readFileSync(path.join(ROOT, f), 'utf8');
    L.push('  modules[' + JSON.stringify(f) + '] = function (module, exports, require) {');
    L.push(src);
    L.push('  };');
}

L.push('  function requireFrom(id) {');
L.push('    return function (spec) {');
L.push('      var resolved = resolve(id, spec);');
L.push('      if (cache[resolved]) return cache[resolved].exports;');
L.push('      if (!modules[resolved]) throw new Error("Bundle: module not found: " + resolved + " (required from " + id + ")");');
L.push('      var m = cache[resolved] = { exports: {} };');
L.push('      modules[resolved](m, m.exports, requireFrom(resolved));');
L.push('      return m.exports;');
L.push('    };');
L.push('  }');
L.push('  function resolve(from, spec) {');
L.push('    if (spec.charAt(0) !== ".") return spec;');
L.push('    var parts = from.split("/").slice(0, -1).concat(spec.split("/"));');
L.push('    var out = [];');
L.push('    for (var i = 0; i < parts.length; i++) { var p = parts[i]; if (p === "" || p === ".") continue; if (p === "..") out.pop(); else out.push(p); }');
L.push('    return out.join("/");');
L.push('  }');
L.push('  var api = requireFrom("index.js")("index.js");');
L.push('  global.KYMON_IQ = api;');
L.push('})(typeof window !== "undefined" ? window : globalThis);');

const dest = path.join(ROOT, 'qimen-interpreter.bundle.js');
fs.writeFileSync(dest, L.join('\n'), 'utf8');
console.log('bundle written:', dest);

